// prisma/data/curated.ts
// Hand-curated seed data derived from DT4A GTFS (OSM) + verified anchors.
// Anchors inserted first, GTFS stops commune-inferred via nearest anchor.

import { StopType, TransportType } from '../../generated/prisma';

// ─── TYPES ────────────────────────────────────────────────────────────────

export interface AnchorStop {
  name: string;
  commune: string;
  latitude: number;
  longitude: number;
  type: StopType;
}

export interface GtfsStopDef {
  canonicalName: string;
  latitude: number;
  longitude: number;
  gtfsStopIds: string[];
}

export interface CuratedRoute {
  name: string;
  transportType: TransportType;
  stops: string[];
  durations: number[];
}

export interface PriceBand {
  maxKm: number;
  price: number;
}

